// NewCreateQueryPayload builds a explore service createQuery endpoint payload.
func NewCreateQueryPayload(body *CreateQueryRequestBody, sessionToken *string, projectSlugInput *string) *explore.CreateQueryPayload {
	v := &explore.CreateQueryPayload{
		Name:    *body.Name,
		Dataset: *body.Dataset,
	}
	v.Spec = make(map[string]any, len(body.Spec))
	for key, val := range body.Spec {
		tk := key
		tv := val
		v.Spec[tk] = tv
	}
	v.SessionToken = sessionToken
	v.ProjectSlugInput = projectSlugInput

	return v
}

// NewUpdateQueryPayload builds a explore service updateQuery endpoint payload.
