// ValidateCreateQueryRequestBody runs the validations defined on
// CreateQueryRequestBody
func ValidateCreateQueryRequestBody(body *CreateQueryRequestBody) (err error) {
	if body.Name == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("name", "body"))
	}
	if body.Dataset == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("dataset", "body"))
	}
	if body.Spec == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("spec", "body"))
	}
	if body.Name != nil {
		if utf8.RuneCountInString(*body.Name) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.name", *body.Name, utf8.RuneCountInString(*body.Name), 1, true))
		}
	}
	if body.Name != nil {
		if utf8.RuneCountInString(*body.Name) > 200 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.name", *body.Name, utf8.RuneCountInString(*body.Name), 200, false))
		}
	}
	if body.Dataset != nil {
		if utf8.RuneCountInString(*body.Dataset) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.dataset", *body.Dataset, utf8.RuneCountInString(*body.Dataset), 1, true))
		}
	}
	return
}

// ValidateUpdateQueryRequestBody runs the validations defined on
// UpdateQueryRequestBody
func ValidateUpdateQueryRequestBody(body *UpdateQueryRequestBody) (err error) {
	if body.ID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("id", "body"))
	}
	if body.Name == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("name", "body"))
	}
	if body.Dataset == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("dataset", "body"))
	}
	if body.Spec == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("spec", "body"))
	}
	if body.ID != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.id", *body.ID, goa.FormatUUID))
	}
	if body.Name != nil {
		if utf8.RuneCountInString(*body.Name) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.name", *body.Name, utf8.RuneCountInString(*body.Name), 1, true))
		}
	}
	if body.Name != nil {
		if utf8.RuneCountInString(*body.Name) > 200 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.name", *body.Name, utf8.RuneCountInString(*body.Name), 200, false))
		}
	}
	if body.Dataset != nil {
		if utf8.RuneCountInString(*body.Dataset) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.dataset", *body.Dataset, utf8.RuneCountInString(*body.Dataset), 1, true))
		}
	}
	return
}
